\label{thm:line}
Put
\begin{align}
 \kappa&=1-\frac{n}{2},\notag\\
 P&=\frac{(n-k+r)(k-r)}{\Delta^2}=-(a+1)(b+1),&
 Q&=\frac{(n-k+s)(k-s)}{\Delta^2}=-ab.\label{eq:PQ}
\end{align}
A probability law $\mu$ is a UAM time law if and only if its moments satisfy
\begin{equation}\label{eq:line}
 \boxed{\quad x=\kappa+P\eta,\quad y=\kappa+Q\eta,\quad z=1-\eta
 \quad\text{for some }\eta\in[0,2].\quad}
\end{equation}
Here $\eta=1-z$ is a moment parameter, not an observation time.

\label{thm:twoatoms}
Let $G$ be a connected strongly regular graph that is not complete, and let $\mu$ be any Borel probability
law on $[0,\infty)$. Then there exist $t_1,t_2\ge0$ and $p\in[0,1]$
such that
\begin{equation}\label{eq:twoaverage}
 \boxed{\quad
 \int M(t)\,d\mu(t)=pM(t_1)+(1-p)M(t_2).
 \quad}
\end{equation}
If $\mu$ is concentrated on a compact interval $[a,b]$, both times can
be chosen in $[a,b]$. In particular,
\begin{equation}\label{eq:twouam}
 \boxed{\quad
 G\text{ admits UAM}
 \quad\Longleftrightarrow\quad
 \exists\,p\in[0,1],\ t_1,t_2\ge0\ \text{ with }
 \ pM(t_1)+(1-p)M(t_2)=\frac{1}{n}J .
 \quad}
\end{equation}

\label{cor:two-time-test}
Put
\[
 \Psi(t)=\left(\beta_1(t)-\frac{1}{n},\ \beta_2(t)-\frac{1}{n}\right)\in\mathbb R^2 .
\]
Then $G$ admits UAM if and only if either $\Psi(t)=0$ at some time, or
there are $t_1,t_2\ge0$ for which
\begin{equation}\label{eq:opposite}
 \det[\Psi(t_1),\Psi(t_2)]=0,\quad
 \Psi(t_1)\mathbin{\cdot}\Psi(t_2)<0 .
\end{equation}
In the second case an exact UAM law is
\begin{equation}\label{eq:two-weights}
 \mu=p\delta_{t_1}+(1-p)\delta_{t_2},\quad
 p=\frac{\lVert\Psi(t_2)\rVert_2}
         {\lVert\Psi(t_1)\rVert_2+\lVert\Psi(t_2)\rVert_2}.
\end{equation}

\label{lem:conference}
If the restricted eigenvalues are nonintegral, then $n$ is not a square and
\begin{equation}\label{eq:conference}
 k=\frac{n-1}{2},\quad \lambda=\frac{n-5}{4},\quad
 \nu=\frac{n-1}{4},\quad
 r=\frac{-1+\sqrt n}{2},\quad s=\frac{-1-\sqrt n}{2}.
\end{equation}
The multiplicities of $r$ and $s$ are both $\displaystyle\frac{n-1}{2}$.

\label{thm:conference}
For every connected strongly regular graph that is not complete and has nonintegral restricted eigenvalues, choose
\begin{equation}\label{eq:Tbound}
 T\ge\frac{32(n-1)B}{\rho}
   =\frac{32(n^2-4n+5)}{\rho}.
\end{equation}
Let
\[
 f(t)=\begin{pmatrix}1\\\cos(\omega_1t)\\\cos(\omega_2t)\\\cos(\omega_3t)\end{pmatrix},
 \quad
 G_T=\frac{1}{T}\int_0^T f(t)f(t)^{\mathsf T}\,dt,\quad
 a_T=\frac{1}{T}\int_0^T W(t)f(t)\,dt
\]
and put
\begin{equation}\label{eq:correction}
 q_T=G_T^{-1}(\mathbf d-a_T).
\end{equation}
Then
\begin{equation}\label{eq:timedensity}
 \boxed{\quad
 d\mu_T(t)=\frac{\mathbf1_{[0,T]}(t)}{T}
          \left(W(t)+q_T^{\mathsf T}f(t)\right)\,dt
 \quad}
\end{equation}
is a probability law with \eqref{eq:conference-target}, and hence is a UAM time law.
Its density is bounded and is at least $\displaystyle\frac{1}{2T(n-1)}$ on $[0,T]$.

\label{thm:toeplitz}
A connected strongly regular graph that is not complete and has integral spectrum admits UAM if and only if there exist
$c_0,\ldots,c_D\in\mathbb R$ and $\eta\in[0,2]$ such that
\begin{equation}\label{eq:SDP}
 \boxed{\begin{gathered}
 c_0=1,\quad \mathcal T_D(c)\succeq0,\quad 0\le\eta\le2,\\
 c_{a_0}=\kappa+P\eta,\quad
 c_{a_0+b_0}=\kappa+Q\eta,\quad
 c_{b_0}=1-\eta .
 \end{gathered}}
\end{equation}
Repeated indices denote the same variable and must satisfy all displayed equations.
The constants $\kappa,P,Q$ are those of \eqref{eq:PQ}.

\label{lem:gram-hadamard}
The following two statements are equivalent.
\begin{enumerate}
 \item[(a)] The moment line \eqref{eq:line}, with $\eta$ allowed to be any real number, contains a point $(x,y,z)$ with $C(x,y,z)\succeq0$.
 \item[(b)] There are complex numbers $\zeta_1,\zeta_2$ of modulus one such that $\mathcal H=I+\zeta_1A+\zeta_2(J-I-A)$ satisfies $\mathcal H\mathcal H^*=nI$.
\end{enumerate}
If $G$ admits UAM, then (a) holds by Theorem~\ref{thm:line} and Remark~\ref{rem:gram}.

\label{thm:chan}
Let $G$ be primitive and satisfy the equivalent conditions (a) and (b) of Lemma~\ref{lem:gram-hadamard}. Then $G$ or its complement has one of the following parameter sets, where $\theta$ denotes the positive restricted eigenvalue of the graph in the list.
\begin{enumerate}
 \item[(i)] $(4\theta^2,\,2\theta^2-\theta,\,\theta^2-\theta,\,\theta^2-\theta)$, the Latin square type.
 \item[(ii)] $(4\theta^2,\,2\theta^2+\theta,\,\theta^2+\theta,\,\theta^2+\theta)$, the negative Latin square type.
 \item[(iii)] $(4\theta^2-1,\,2\theta^2,\,\theta^2,\,\theta^2)$, the symplectic type.
 \item[(iv)] $(4\theta^2+4\theta+1,\,2\theta^2+2\theta,\,\theta^2+\theta-1,\,\theta^2+\theta)$, the conference graphs.
 \item[(v)] $(4\theta^2+4\theta+2,\,2\theta^2+\theta,\,\theta^2-1,\,\theta^2)$, the regular conference matrix type.
\end{enumerate}

\label{lem:three-ineq}
Let $G$ be primitive, and put
\[
 \tau=2k-r-s-n,\qquad \Xi=n+2\tau-4\nu,\qquad \sigma=(r+s+1)^2 .
\]
Then $\tau$ and $\Xi$ are integers, $\sigma$ is the square of the integer $\lambda-\nu+1$, and
\begin{equation}\label{eq:j-sigma}
 \Delta^2=\tau^2+\Xi n,\qquad \sigma=\Delta^2-n+1-\Xi .
\end{equation}
If the moment line \eqref{eq:line} contains a point with $C(x,y,z)\succeq0$, then
\begin{equation}\label{eq:three-ineq}
 \Delta^2\le\frac{n^2}{n-4},\qquad \tau^2\le\frac{n^2}{n-4},\qquad \Delta^2\ge\frac{n(\sigma-1)}{2}.
\end{equation}

\label{prop:latin}
Let $G$ or its complement have parameters (i) or (ii). The following statements are equivalent.
\begin{enumerate}
 \item[(a)] $G$ admits UAM.
 \item[(b)] $G$ admits instantaneous uniform mixing.
 \item[(c)] $\theta$ is even.
\end{enumerate}
In this case a probability law is a UAM time law if and only if it is concentrated on the set $\displaystyle S_\theta=\left\{\frac{(2j+1)\pi}{2\theta}\,\middle|\,j=0,1,2,\ldots\right\}$, and every point of $S_\theta$ is a time of instantaneous uniform mixing. In particular no absolutely continuous law gives UAM.

Here $\delta=2\theta+1$, $a_0=\theta$, $b_0=1$ and $D=\theta+1$. Let $\varrho$ be the image of a time law $\mu$ under $t\mapsto\xi=\cos((2\theta+1)t)$, and put $w=1+\xi\in[0,2]$ and $\displaystyle\overline w=\int w\,d\varrho$. Then $\displaystyle x=\int\mathsf T_\theta\,d\varrho$, $\displaystyle y=\int\mathsf T_{\theta+1}\,d\varrho$ and $\displaystyle z=\int\xi\,d\varrho=\overline w-1$. Since $P=Q$, a UAM law satisfies $x=y$, and \eqref{eq:conference-line} becomes
\begin{equation}\label{eq:square-conf}
 x=y=\frac{1}{2}-(\theta^2+\theta)\,\overline w.
\end{equation}
From $\mathsf T_m'(\cos\phi)\sin\phi=m\sin(m\phi)$ and $|\sin(m\phi)|\le m|\sin\phi|$ we get Markov's bound $|\mathsf T_m'|\le m^2$ on $[-1,1]$. Hence $\mathsf T_m(1-w)\ge1-m^2w$ for $w\in[0,2]$, while $\mathsf T_m(-1+w)=(-1)^m\mathsf T_m(1-w)$.

Let $m_e$ be the even one of $\theta$ and $\theta+1$. The corresponding moment is at least $1-m_e^2\overline w$, so \eqref{eq:square-conf} gives $\displaystyle(m_e^2-\theta^2-\theta)\,\overline w\ge\frac{1}{2}$. If $\theta$ is even, then $m_e=\theta$ and the left side equals $-\theta\overline w\le0$, a contradiction. If $\theta$ is odd, then $m_e=\theta+1$ and $\displaystyle\overline w\ge\frac{1}{2(\theta+1)}$. The other moment is at least $-1$, so \eqref{eq:square-conf} gives $\displaystyle\overline w\le\frac{3}{2\theta(\theta+1)}$. Together these force $\theta\le3$. If $\theta=3$, equality holds throughout, so $\displaystyle\overline w=\frac{1}{8}$ and $x=y=-1$. Then $\mathsf T_3(\xi)=-1$ and $\mathsf T_4(\xi)=-1$ hold $\varrho$-almost everywhere. This is impossible, because $\mathsf T_3(\xi)=-1$ only for $\displaystyle\xi\in\left\{-1,\frac{1}{2}\right\}$, where $\mathsf T_4$ takes the values $1$ and $\displaystyle-\frac{1}{2}$. Hence $\theta=1$, and for $n=9$ the law \eqref{eq:nine} gives UAM.

\label{thm:classification}
Let $G$ be a connected strongly regular graph on $n$ vertices that is not complete. Then $G$ admits a UAM time law if and only if one of the following holds.
\begin{enumerate}
 \item[(a)] $G$ is a conference graph, and $n$ is not a square or $n=9$.
 \item[(b)] $G$ or its complement has parameters $(4\theta^2+4\theta+2,\,2\theta^2+\theta,\,\theta^2-1,\,\theta^2)$ with $\theta\ge1$.
 \item[(c)] $G$ or its complement has parameters $(4\theta^2-1,\,2\theta^2,\,\theta^2,\,\theta^2)$ with $\theta\ge2$.
 \item[(d)] $G$ or its complement has parameters $(4\theta^2,\,2\theta^2-\theta,\,\theta^2-\theta,\,\theta^2-\theta)$ or $(4\theta^2,\,2\theta^2+\theta,\,\theta^2+\theta,\,\theta^2+\theta)$ with $\theta\ge2$ even.
 \item[(e)] $G$ is the $4$-cycle $C_4$.
\end{enumerate}
